(7652995, 1245481, 4008, '<td valign="top">I love the colors and the simplicity of the scene, very attractive. Feels like a painting. What kind of processing did you do?<br/>Small point: Did you add the shadow of the bike stand? Does not seem right.</td>', 'I love the colors and the simplicity of the scene, very attractive. Feels like a painting. What kind of processing did you do?Small point: Did you add the shadow of the bike stand? Does not seem right.', '2020-02-08 05:18:37.000000', NULL, 1),
(7652996, 1245258, 4008, '<td valign="top">Simply stunning, work of art.</td>', 'Simply stunning, work of art.', '2020-02-08 05:19:36.000000', NULL, 1),
(7652997, 1245593, 4008, '<td valign="top">Beautiful scene, I am missing some contrast/shadow, still one of my favourites in this challenge.</td>', 'Beautiful scene, I am missing some contrast/shadow, still one of my favourites in this challenge.', '2020-02-08 05:21:07.000000', NULL, 1),
